mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  p.xz = rot(time * 0.3) * p.xz;
  float s = length(p) - 1.15;
  float bumps = sin(p.x * 4.0) * sin(p.y * 4.0) * sin(p.z * 4.0) * 0.18;
  return s + bumps;
}
